<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, shallowRef, watch } from 'vue'
import { useRouter } from 'vue-router'
import type * as Monaco from 'monaco-editor/esm/vs/editor/editor.api'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Search, Plus, Refresh, FolderOpened, Document, VideoPlay, Select, Clock, MoreFilled, FullScreen, Download, DataAnalysis, CircleCheckFilled, Close } from '@element-plus/icons-vue'
import { dataSourceApi } from '../../api/platform'
import { developmentApi, metadataApi, releaseApi, type ColumnView, type DataSourceView, type DevFile, type DevProject, type FileVersion, type LineageView, type QueryHistory, type QueryResult, type TableProfile, type TableView } from '../../api/domain'

const router=useRouter()
const projects=ref<DevProject[]>([]),files=ref<DevFile[]>([]),sources=ref<DataSourceView[]>([]),databases=ref<string[]>([]),tables=ref<TableView[]>([])
const projectId=ref<number>(),file=ref<DevFile>(),sourceId=ref<number>(),database=ref(''),result=ref<QueryResult>(),output=ref('')
const openFiles=ref<DevFile[]>([]),activeBottom=ref('result'),resourceTab=ref('mine'),resourceSearch=ref(''),tableSearch=ref('')
const saving=ref(false),running=ref(false),loading=ref(false),filesLoading=ref(false),metadataLoading=ref(false),editorLoading=ref(false),resultExpanded=ref(false)
const editorHost=ref<HTMLElement>(),editor=shallowRef<Monaco.editor.IStandaloneCodeEditor>()
const selectedTableName=ref(''),columns=ref<ColumnView[]>([]),profile=ref<TableProfile>(),historyRows=ref<QueryHistory[]>([]),versions=ref<FileVersion[]>([]),lineage=ref<LineageView[]>([])
let monacoApi:typeof import('monaco-editor/esm/vs/editor/editor.api')|null=null
const restoring=ref(true),DEV_STATE_KEY='datasphere:development:state:v2'
type DevState={projectId?:number;fileId?:number;sourceId?:number;database?:string;activeBottom?:string}
const filteredFiles=computed(()=>{const q=resourceSearch.value.trim().toLowerCase();return q?files.value.filter(x=>x.name.toLowerCase().includes(q)):files.value})
const filteredTables=computed(()=>{const q=tableSearch.value.trim().toLowerCase();return q?tables.value.filter(x=>x.name.toLowerCase().includes(q)):tables.value})
const selectedTable=computed(()=>tables.value.find(x=>x.name===selectedTableName.value))
function readState():DevState{try{return JSON.parse(sessionStorage.getItem(DEV_STATE_KEY)||'{}')}catch{return {}}}
function persistState(){if(restoring.value)return;sessionStorage.setItem(DEV_STATE_KEY,JSON.stringify({projectId:projectId.value,fileId:file.value?.id,sourceId:sourceId.value,database:database.value,activeBottom:activeBottom.value}))}
function msg(e:unknown){return e instanceof Error?e.message:'操作失败'}
function scheduleEditorInit(){const start=()=>void initEditor();const idle=(window as Window & {requestIdleCallback?:(cb:()=>void,o?:{timeout:number})=>number}).requestIdleCallback;idle?idle(start,{timeout:500}):globalThis.setTimeout(start,0)}
async function initEditor(){if(!editorHost.value||editor.value||editorLoading.value)return;editorLoading.value=true;try{monacoApi??=await import('monaco-editor/esm/vs/editor/editor.api');await import('monaco-editor/esm/vs/basic-languages/sql/sql.contribution');if(!editorHost.value||editor.value)return;editor.value=monacoApi.editor.create(editorHost.value,{value:file.value?.content||'-- 新建 SQL\nSELECT 1;',language:'sql',theme:'vs',automaticLayout:true,minimap:{enabled:false},fontSize:14,lineHeight:23,scrollBeyondLastLine:false,padding:{top:12},renderLineHighlight:'line',wordWrap:'off'});editor.value.addCommand(monacoApi.KeyMod.CtrlCmd|monacoApi.KeyCode.Enter,()=>void run(false));editor.value.onDidChangeModelContent(()=>{if(file.value)file.value={...file.value,content:editor.value?.getValue()||''}})}catch(e){ElMessage.error('SQL 编辑器加载失败：'+msg(e))}finally{editorLoading.value=false}}
async function boot(){loading.value=true;const state=readState();try{const [ps,ds]=await Promise.all([developmentApi.projects(),dataSourceApi.list()]);projects.value=ps;sources.value=ds.filter(x=>x.type==='STARROCKS');projectId.value=(ps.find(x=>x.id===state.projectId)||ps[0])?.id;sourceId.value=(sources.value.find(x=>x.id===state.sourceId)||sources.value[0])?.id;if(['result','log','history','version','lineage'].includes(state.activeBottom||''))activeBottom.value=state.activeBottom!;loading.value=false;await nextTick();scheduleEditorInit();const jobs:Promise<void>[]=[];if(projectId.value)jobs.push(loadFiles(state.fileId));if(sourceId.value)jobs.push(loadDatabases(state.database));await Promise.all(jobs)}catch(e){ElMessage.error(msg(e))}finally{restoring.value=false;persistState();loading.value=false}}
async function loadFiles(preferred?:number){if(!projectId.value)return;filesLoading.value=true;try{files.value=await developmentApi.files(projectId.value);const target=files.value.find(x=>x.id===preferred)||files.value[0];if(target)await openFile(target)}finally{filesLoading.value=false}}
async function openFile(row:DevFile){const detail=await developmentApi.getFile(row.id);const current=file.value;if(current&&editor.value)current.content=editor.value.getValue();file.value=detail;const i=openFiles.value.findIndex(x=>x.id===detail.id);if(i<0)openFiles.value.push(detail);else openFiles.value[i]=detail;editor.value?.setValue(detail.content||'');persistState();if(activeBottom.value==='version')void loadVersions()}
function activateTab(row:DevFile){void openFile(openFiles.value.find(x=>x.id===row.id)||row)}
function closeTab(row:DevFile,event:Event){event.stopPropagation();const idx=openFiles.value.findIndex(x=>x.id===row.id);if(idx<0)return;openFiles.value.splice(idx,1);if(file.value?.id===row.id){const next=openFiles.value[Math.max(0,idx-1)];if(next)void openFile(next);else{file.value=undefined;editor.value?.setValue('-- 请选择或新建 SQL 文件\nSELECT 1;')}}}
async function newFile(){if(!projectId.value)return ElMessage.warning('暂无可用研发项目');try{const {value}=await ElMessageBox.prompt('请输入 SQL 文件名称','新建 SQL',{inputValue:`query_${new Date().toISOString().slice(0,10).replaceAll('-','')}.sql`,inputPattern:/^[^\\/:*?"<>|]+$/,inputErrorMessage:'文件名不合法',confirmButtonText:'创建',cancelButtonText:'取消'});const name=value.endsWith('.sql')?value:`${value}.sql`;const created=await developmentApi.createFile({projectId:projectId.value,name,fileType:'SQL',content:'-- DataSphere SQL\nSELECT 1;',description:'SQL 开发文件'});await loadFiles(created.id);ElMessage.success('SQL 文件已创建')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}
async function save(){if(!file.value||!editor.value)return;saving.value=true;try{file.value=await developmentApi.saveFile(file.value.id,{content:editor.value.getValue(),name:file.value.name,description:file.value.description});const idx=openFiles.value.findIndex(x=>x.id===file.value?.id);if(idx>=0)openFiles.value[idx]=file.value;ElMessage.success(`已保存 V${file.value.currentVersion}`)}catch(e){ElMessage.error(msg(e))}finally{saving.value=false}}
async function publish(){if(!file.value)return ElMessage.warning('请选择 SQL 文件');try{await releaseApi.request({resourceType:'DEVELOPMENT',resourceId:file.value.id,resourceName:file.value.name,requestedVersion:file.value.currentVersion});ElMessage.success('发布请求已提交')}catch(e){ElMessage.error(msg(e))}}
async function run(explain=false){if(!sourceId.value||!editor.value)return ElMessage.warning('请选择 StarRocks 数据源');running.value=true;activeBottom.value='result';try{const model=editor.value.getModel();const selection=editor.value.getSelection();const sql=model&&(selection&&!selection.isEmpty()?model.getValueInRange(selection):model.getValue())||'';result.value=await developmentApi.query(explain?`EXPLAIN ${sql}`:sql,sourceId.value,database.value||undefined);output.value=`${result.value.status} · ${result.value.rowCount} 行 · ${result.value.elapsedMs} ms`;void loadHistory()}catch(e){output.value=msg(e);ElMessage.error(output.value)}finally{running.value=false}}
async function loadDatabases(preferred?:string){if(!sourceId.value)return;metadataLoading.value=true;try{const rows=await metadataApi.databases(sourceId.value,'STARROCKS');databases.value=rows.map(x=>x.name);database.value=preferred&&databases.value.includes(preferred)?preferred:(databases.value.includes(database.value)?database.value:databases.value[0]||'');await loadTables()}finally{metadataLoading.value=false}}
async function loadTables(){if(!sourceId.value||!database.value){tables.value=[];return}metadataLoading.value=true;try{tables.value=await metadataApi.tables(sourceId.value,database.value);if(!tables.value.some(x=>x.name===selectedTableName.value))selectedTableName.value=tables.value[0]?.name||'';if(selectedTableName.value)await loadTableDetail()}finally{metadataLoading.value=false}}
async function loadTableDetail(){if(!sourceId.value||!database.value||!selectedTableName.value){columns.value=[];profile.value=undefined;return}metadataLoading.value=true;try{const [cols,p]=await Promise.all([metadataApi.columns(sourceId.value,database.value,selectedTableName.value),metadataApi.profile(sourceId.value,database.value,selectedTableName.value)]);columns.value=cols;profile.value=p}catch(e){columns.value=[];profile.value=undefined}finally{metadataLoading.value=false}}
function chooseTable(name:string){selectedTableName.value=name;void loadTableDetail()}
function insertSelectedTable(){if(!selectedTableName.value||!editor.value)return;const sel=editor.value.getSelection();if(sel)editor.value.executeEdits('metadata',[{range:sel,text:`\`${database.value}\`.\`${selectedTableName.value}\``,forceMoveMarkers:true}]);editor.value.focus()}
async function loadHistory(){try{historyRows.value=(await developmentApi.history()).slice(0,50)}catch{historyRows.value=[]}}
async function loadVersions(){if(!file.value)return;try{versions.value=await developmentApi.versions(file.value.id)}catch{versions.value=[]}}
async function loadLineage(){if(!selectedTableName.value)return;try{lineage.value=await metadataApi.lineage(selectedTableName.value)}catch{lineage.value=[]}}
function format(){editor.value?.getAction('editor.action.formatDocument')?.run()}
function help(text:string){ElMessage.info(`${text}正在完善中`)}
function downloadResult(){if(!result.value?.rows?.length)return ElMessage.warning('暂无可导出结果');const cols=result.value.columns;const csv=[cols.join(','),...result.value.rows.map(r=>cols.map(c=>JSON.stringify(r[c]??'')).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=`query_result_${Date.now()}.csv`;a.click();URL.revokeObjectURL(a.href)}
function fmtTime(v?:string){return v?v.replace('T',' ').slice(0,19):'—'}
function fmtSize(v?:number){if(v==null)return '—';if(v<1024)return `${v} B`;if(v<1024**2)return `${(v/1024).toFixed(1)} KB`;if(v<1024**3)return `${(v/1024**2).toFixed(1)} MB`;return `${(v/1024**3).toFixed(1)} GB`}
watch(projectId,()=>{if(!restoring.value)void loadFiles()});watch(sourceId,()=>{if(!restoring.value)void loadDatabases()});watch(database,()=>{if(!restoring.value){void loadTables();persistState()}});watch(selectedTableName,()=>{if(!restoring.value)void loadTableDetail()});watch(activeBottom,v=>{persistState();if(v==='history')void loadHistory();if(v==='version')void loadVersions();if(v==='lineage')void loadLineage()});watch(()=>file.value?.id,persistState);watch(projectId,persistState);watch(sourceId,persistState)
onMounted(boot);onBeforeUnmount(()=>{persistState();editor.value?.dispose()})
</script>

<template>
<div class="dev-page" v-loading="loading">
  <section class="workspace">
    <aside class="resource-pane" v-loading="filesLoading">
      <div class="pane-head"><strong>资源管理</strong><div><el-button text circle :icon="Search"/><el-button text circle :icon="Plus" @click="newFile"/><el-button text circle :icon="Refresh" @click="loadFiles()"/></div></div>
      <div class="resource-tabs"><button :class="{on:resourceTab==='mine'}" @click="resourceTab='mine'">我的开发</button><button :class="{on:resourceTab==='recent'}" @click="resourceTab='recent'">最近使用</button><button :class="{on:resourceTab==='favorite'}" @click="resourceTab='favorite'">收藏</button></div>
      <div class="resource-search"><el-input v-model="resourceSearch" size="small" placeholder="搜索 SQL 文件" :prefix-icon="Search" clearable/></div>
      <div class="tree-root"><div class="tree-label"><el-icon><FolderOpened/></el-icon><strong>{{projects.find(x=>x.id===projectId)?.name||'研发项目'}}</strong></div>
        <div class="layer"><span class="folder-caret">⌄</span><span class="folder-dot"></span><strong>SQL 开发</strong></div>
        <button v-for="f in filteredFiles" :key="f.id" class="file-node" :class="{active:file?.id===f.id}" @click="openFile(f)"><el-icon><Document/></el-icon><span>{{f.name}}</span></button>
      </div>
      <div class="tree-footer"><button>› 函数资源</button><button>› 临时查询</button><button>› 回收站</button></div>
    </aside>

    <main class="center-pane" :class="{'result-expanded':resultExpanded}">
      <div class="file-tabs"><button v-for="tab in openFiles" :key="tab.id" :class="{active:file?.id===tab.id}" @click="activateTab(tab)"><el-icon><Document/></el-icon><span>{{tab.name}}</span><el-icon class="tab-close" @click="closeTab(tab,$event)"><Close/></el-icon></button><button class="new-tab" @click="newFile">＋</button></div>
      <div class="editor-toolbar">
        <div class="toolbar-left"><el-button type="primary" :loading="running" :icon="VideoPlay" @click="run(false)">运行</el-button><el-button disabled>停止</el-button><el-button :loading="saving" :icon="Select" @click="save">保存</el-button><el-button @click="format">格式化</el-button><el-button :icon="Clock" @click="router.push('/workflow/definitions')">调度</el-button><el-dropdown><el-button>更多 <el-icon><MoreFilled/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="run(true)">EXPLAIN 执行计划</el-dropdown-item><el-dropdown-item @click="publish">发布当前版本</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div>
        <div class="toolbar-right"><span class="env-dot"></span><el-select v-model="sourceId" size="small" style="width:155px" placeholder="开发环境"><el-option v-for="s in sources" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-select v-model="database" size="small" style="width:135px" placeholder="数据库"><el-option v-for="d in databases" :key="d" :label="d" :value="d"/></el-select><el-button circle :icon="FullScreen" @click="help('编辑器全屏')"/></div>
      </div>
      <div class="editor-shell"><div ref="editorHost" class="editor-host"/><div v-if="editorLoading&&!editor" class="editor-loading">正在加载 SQL 编辑器…</div></div>
      <section class="bottom-panel">
        <div class="bottom-tabs"><button v-for="item in [['result','结果'],['log','日志'],['history','执行历史'],['version','版本'],['lineage','血缘']]" :key="item[0]" :class="{on:activeBottom===item[0]}" @click="activeBottom=item[0]">{{item[1]}}</button><div class="bottom-actions"><el-button v-if="activeBottom==='result'" size="small" :icon="Download" @click="downloadResult">导出</el-button><el-button v-if="activeBottom==='result'" size="small" :icon="DataAnalysis" @click="help('结果图表')">图表</el-button><el-button size="small" circle :icon="FullScreen" @click="resultExpanded=!resultExpanded"/></div></div>
        <div v-if="activeBottom==='result'" class="result-content"><div class="run-summary" :class="{'ok':result?.status==='SUCCESS'}"><el-icon><CircleCheckFilled/></el-icon><strong>{{result?result.status==='SUCCESS'?'执行成功':result.status:'尚未执行'}}</strong><span v-if="result">耗时 {{result.elapsedMs}} ms</span><span v-if="result">返回 {{result.rowCount}} 条数据</span></div><el-table v-if="result?.rows?.length" :data="result.rows" height="205" size="small"><el-table-column v-for="c in result.columns" :key="c" :prop="c" :label="c" min-width="130" show-overflow-tooltip/></el-table><div v-else class="empty-result">运行 SQL 后在这里查看结果</div></div>
        <pre v-else-if="activeBottom==='log'" class="log-panel">{{output||'暂无执行日志'}}</pre>
        <div v-else-if="activeBottom==='history'" class="bottom-table"><el-table :data="historyRows" height="220" size="small"><el-table-column prop="startedAt" label="执行时间" width="168"><template #default="s">{{fmtTime(s.row.startedAt)}}</template></el-table-column><el-table-column prop="username" label="执行人" width="100"/><el-table-column prop="databaseName" label="数据库" width="130"/><el-table-column prop="sql" label="SQL" min-width="260" show-overflow-tooltip/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="elapsedMs" label="耗时(ms)" width="100"/></el-table></div>
        <div v-else-if="activeBottom==='version'" class="bottom-table"><el-table :data="versions" height="220" size="small"><el-table-column prop="versionNo" label="版本" width="90"><template #default="s">V{{s.row.versionNo}}</template></el-table-column><el-table-column prop="publishFlag" label="发布状态" width="110"><template #default="s">{{s.row.publishFlag?'已发布':'未发布'}}</template></el-table-column><el-table-column prop="checksum" label="校验值" show-overflow-tooltip/></el-table></div>
        <div v-else class="lineage-panel"><div v-if="lineage.length" v-for="x in lineage" :key="x.id" class="lineage-row"><span>{{x.sourceTable}}</span><b>→</b><span>{{x.targetTable}}</span><em>{{x.relationType}}</em></div><div v-else class="empty-result">选择右侧表后查看血缘关系</div></div>
      </section>
    </main>

    <aside class="info-pane" v-loading="metadataLoading">
      <div class="info-pane-title">表信息</div>
      <div class="table-info">
        <div class="table-select"><el-select v-model="selectedTableName" filterable placeholder="选择数据表" style="width:100%"><el-option v-for="t in filteredTables" :key="t.name" :label="t.name" :value="t.name"/></el-select></div>
        <div v-if="selectedTableName" class="table-title"><span class="table-symbol">▣</span><div><strong>{{selectedTableName}}</strong><p>{{selectedTable?.comment||'暂无表描述'}}</p></div><el-button text type="primary" @click="insertSelectedTable">插入</el-button></div>
        <div v-if="selectedTableName" class="profile-grid"><span>所属数据库</span><strong>{{database||'—'}}</strong><span>表类型</span><strong>{{selectedTable?.type||'TABLE'}}</strong><span>负责人</span><strong>{{profile?.owner||'—'}}</strong><span>数据量</span><strong>{{profile?.rowCount==null?'—':profile.rowCount.toLocaleString()+' 行'}}</strong><span>存储大小</span><strong>{{fmtSize(profile?.estimatedSizeBytes)}}</strong><span>创建时间</span><strong>{{fmtTime(profile?.createTime)}}</strong><span>更新时间</span><strong>{{fmtTime(profile?.updateTime)}}</strong></div>
        <div class="field-head"><strong>字段信息</strong><span>共 {{columns.length}} 个字段</span></div><div class="field-search"><el-input v-model="tableSearch" size="small" placeholder="搜索表..." :prefix-icon="Search" clearable/></div>
        <div class="field-table"><table><thead><tr><th>字段名</th><th>类型</th><th>描述</th></tr></thead><tbody><tr v-for="c in columns" :key="c.name"><td>{{c.name}}</td><td>{{c.dataType}}</td><td>{{c.comment||'—'}}</td></tr></tbody></table></div>
        <div class="nearby-tables"><strong>当前库表</strong><button v-for="t in filteredTables.slice(0,20)" :key="t.name" :class="{active:selectedTableName===t.name}" @click="chooseTable(t.name)">{{t.name}}</button></div>
      </div>
    </aside>
  </section>
</div>
</template>

<style scoped>
