text-align:left;border:0;background:transparent;color:#667085;cursor:pointer}.center-pane{display:grid;grid-template-rows:40px 48px minmax(250px,1fr) 270px}.center-pane.result-expanded{position:fixed;inset:72px 20px 20px;z-index:50;grid-template-rows:0 0 0 1fr}.center-pane.result-expanded>.file-tabs,.center-pane.result-expanded>.editor-toolbar,.center-pane.result-expanded>.editor-shell{display:none}.file-tabs{display:flex;align-items:end;border-bottom:1px solid #e9edf3;background:#fbfcfe;overflow-x:auto}.file-tabs>button{height:40px;max-width:210px;display:flex;align-items:center;gap:7px;padding:0 12px;border:0;border-right:1px solid #e9edf3;background:#f8fafc;color:#667085;font-size:12px;cursor:pointer}.file-tabs>button.active{background:#fff;color:#2878ff;font-weight:650}.file-tabs .tab-close{margin-left:auto;font-size:12px;color:#98a2b3}.file-tabs .new-tab{width:42px;font-size:18px}.editor-toolbar{display:flex;align-items:center;justify-content:space-between;padding:0 10px;border-bottom:1px solid #e9edf3}.toolbar-left,.toolbar-right{display:flex;align-items:center;gap:6px}.toolbar-left :deep(.el-button + .el-button){margin-left:0}.env-dot{width:8px;height:8px;border-radius:50%;background:#24b47e}.editor-shell{position:relative;min-height:0;background:#fff}.editor-host{height:100%}.editor-loading{position:absolute;inset:0;display:grid;place-items:center;background:#fff;color:#98a2b3;font-size:12px}.bottom-panel{min-height:0;border-top:1px solid #e5eaf1;display:flex;flex-direction:column}.bottom-tabs{height:42px;display:flex;align-items:center;padding:0 10px;border-bottom:1px solid #eef1f5}.bottom-tabs>button{height:42px;padding:0 14px;border:0;background:transparent;color:#667085;font-size:12px;cursor:pointer;position:relative}.bottom-tabs>button.on{color:#2878ff;font-weight:700}.bottom-tabs>button.on:after{content:'';position:absolute;left:12px;right:12px;bottom:0;height:2px;background:#2878ff}.bottom-actions{margin-left:auto;display:flex;gap:5px}.result-content,